# Code generated by Claude
"""The operator alert sound: a short two-tone beep, played once when the task policy asks for operator control.

    play_alert()

No audio library is needed: the beep is generated with the standard library (wave) into a Waveform Audio File Format (WAV) file in the temp
directory, once, and played in the background with the Advanced Linux Sound Architecture (ALSA) command `aplay` (present on this virtual machine;
it routes through the sound server). If `aplay` is missing or fails, the terminal bell is written to standard output instead. Never blocks and
never raises.
"""

import math
import shutil
import struct
import subprocess
import sys
import tempfile
import wave
from pathlib import Path

_PATH = Path(tempfile.gettempdir()) / "openarm_tracer_sim_alert.wav"


def _make_wav(path, rate=22050):
    """Writes the alert beep as a mono, 16-bit WAV file.

    The beep is a 880 Hz tone for 0.18 s, 0.07 s of silence, then a 1175 Hz tone for 0.25 s, each tone with a 200-sample fade in and out.

    Args:
        path (str or pathlib.Path): File to write. An existing file is overwritten.
        rate (int): Sample rate in samples per second. Defaults to 22050.
    """
    frames = bytearray()
    for freq, dur in ((880, 0.18), (0, 0.07), (1175, 0.25)):          # a rising two-tone beep
        n = int(rate * dur)
        for i in range(n):
            v = 0 if freq == 0 else int(12000 * math.sin(2 * math.pi * freq * i / rate) * min(1.0, i / 200, (n - i) / 200))
            frames += struct.pack("<h", v)
    with wave.open(str(path), "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(bytes(frames))


def play_alert():
    """Plays the operator alert beep in the background, without blocking.

    The WAV file is created in the temp directory on first use. If `aplay` is installed it is started as a background process; otherwise, or
    if anything fails, the terminal bell character is written to standard output. Exceptions are swallowed.

    Returns:
        bool: True if `aplay` was started, False if the terminal bell fallback was used (whether or not writing it succeeded).
    """
    try:
        if not _PATH.exists():
            _make_wav(_PATH)
        if shutil.which("aplay"):
            subprocess.Popen(["aplay", "-q", str(_PATH)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return True
    except Exception:
        pass
    try:
        sys.stdout.write("\a")
        sys.stdout.flush()
    except Exception:
        pass
    return False
